content:
# Generated by velnor-workflow. Regenerate; do not hand-edit.
name: CI / PR
run-name: CI / PR · ${{ github.event_name }} · ${{ github.ref_name }}

on:
  pull_request:
  workflow_dispatch:
    inputs:
      providers:
        description: Comma-separated provider subset of [github-hosted, velnor]
        required: false
        default: github-hosted,velnor
        type: string
      scope:
        description: Verification scope
        required: true
        default: affected
        type: choice
        options:
          - affected
          - full
      base_sha:
        description: Git ref or SHA used as the affected-selection base
        required: false
        default: refs/heads/main
        type: string


concurrency:
  group: velnor-${{ github.repository }}-${{ github.event.pull_request.number || github.ref }}-pr-${{ github.event.pull_request.number || github.ref }}
  cancel-in-progress: true

permissions:
  actions: read
  contents: read

jobs:
  plan:
    name: "Control / Planning"
    runs-on: ubuntu-24.04
    outputs:
      scope: ${{ steps.plan.outputs.scope }}
      base_sha: ${{ steps.plan.outputs.base_sha }}
      head_sha: ${{ steps.plan.outputs.head_sha }}
      units: ${{ steps.plan.outputs.units }}
      unit_ids: ${{ steps.plan.outputs.unit_ids }}
      full_units: ${{ steps.plan.outputs.full_units }}
      plan_digest: ${{ steps.plan.outputs.plan_digest }}
      excluded: ${{ steps.plan.outputs.excluded }}
      bun_matrix: ${{ steps.plan.outputs.bun_matrix }}
      docker_matrix: ${{ steps.plan.outputs.docker_matrix }}
      docs_matrix: ${{ steps.plan.outputs.docs_matrix }}
      opentofu_matrix: ${{ steps.plan.outputs.opentofu_matrix }}
      rust_matrix: ${{ steps.plan.outputs.rust_matrix }}
    steps:
      - name: Checkout
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          fetch-depth: 0
          persist-credentials: false
      - name: Set up Velnor workflow runtime
        id: runtime
        uses: ./.github/actions/setup-velnor-workflow
        with:
          rev: 0dc79895ff1c5e88be7c3822c437e1c5b5282e12
      - name: Set trusted workflow policy revision
        run: echo "VELNOR_WORKFLOW_POLICY_REVISION=0dc79895ff1c5e88be7c3822c437e1c5b5282e12" >> "$GITHUB_ENV"
      - name: Select affected units
        id: plan
        env:
          EVENT_NAME: ${{ github.event_name }}
          CI_SCOPE_OVERRIDE: ${{ github.event.inputs.scope || '' }}
          BASE_SHA: ${{ github.event.pull_request.base.sha || github.event.inputs.base_sha || github.event.before || 'refs/heads/main' }}
          HEAD_SHA: ${{ github.sha }}
          VELNOR_PROVIDERS: ${{ github.event_name == 'workflow_dispatch' && github.event.inputs.providers || 'github-hosted' }}
          VELNOR_EVENT_TRUSTED: ${{ (!(github.event_name == 'pull_request' && (github.event.pull_request.head.repo.fork || github.event.pull_request.user.type == 'Bot'))) && 'true' || 'false' }}
        run: |
          set -euo pipefail
          if [[ -z "${CI_SCOPE_OVERRIDE:-}" ]]; then unset CI_SCOPE_OVERRIDE; fi
          velnor-workflow plan --config .github/ci/project.toml

      - name: Prepare Velnor workflow runtime
        shell: bash
        env:
          EXPECTED_REVISION: 0dc79895ff1c5e88be7c3822c437e1c5b5282e12
        run: |
          set -euo pipefail
          stage="$RUNNER_TEMP/velnor-workflow-runtime"
          rm -rf "$stage"
          mkdir -p "$stage"
          src="$(command -v velnor-workflow)"
          install -m 0755 "$src" "$stage/velnor-workflow"
          digest="$(sha256sum "$stage/velnor-workflow" | awk '{print $1}')"
          policy_src="${VELNOR_WORKFLOW_PINNED_BINARY:-$src}"
          install -m 0755 "$policy_src" "$stage/velnor-workflow-policy"
          policy_revision="$("$stage/velnor-workflow-policy" --revision)"
          policy_closure="$("$stage/velnor-workflow-policy" --closure)"
          [[ "$policy_closure" == "${{ steps.runtime.outputs.closure }}" ]] || { echo "::error::policy runtime reports closure $policy_closure, expected ${{ steps.runtime.outputs.closure }}" >&2; exit 1; }
          policy_digest="$(sha256sum "$stage/velnor-workflow-policy" | awk '{print $1}')"
          jq -n --arg repository "$GITHUB_REPOSITORY" --arg revision "$EXPECTED_REVISION" --arg closure "${{ steps.runtime.outputs.closure }}" --arg head_branch "${{ github.ref_name }}" --arg platform "${{ runner.os }}-${{ runner.arch }}" --arg run_id "$GITHUB_RUN_ID" --arg job_id "${{ github.job }}" --arg binary_sha256 "$digest" --arg policy_revision "$policy_revision" --arg policy_closure "$policy_closure" --arg policy_binary_sha256 "$policy_digest" '{repository: $repository, revision: $revision, closure: $closure, head_branch: $head_branch, platform: $platform, run_id: $run_id, job_id: $job_id, binary_sha256: $binary_sha256, policy_revision: $policy_revision, policy_closure: $policy_closure, policy_binary_sha256: $policy_binary_sha256}' > "$stage/manifest.json"
      - name: Publish Velnor workflow runtime
        uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a # v7.0.1
        with:
          name: velnor-workflow-runtime-0dc79895ff1c5e88be7c3822c437e1c5b5282e12-${{ runner.os }}-${{ runner.arch }}
          path: ${{ runner.temp }}/velnor-workflow-runtime
          if-no-files-found: error
          retention-days: 7
  github-hosted-bun-velnor:
    name: "Bun · Bun package (velnor) · github-hosted — bun-velnor"
    if: ${{ always() && needs.plan.result == 'success' && contains(needs.plan.outputs.units, '"unit_id":"bun-velnor"') && ((github.event_name == 'workflow_dispatch' && contains(format(',{0},', github.event.inputs.providers), ',github-hosted,')) || (github.event_name != 'workflow_dispatch')) }}
    needs: [plan]
    uses: ./.github/workflows/ci-unit-bun.yml
    with:
      unit: bun-velnor
      provider: github-hosted
      selected_units: ${{ needs.plan.outputs.units }}
      selected_unit_ids: ${{ needs.plan.outputs.unit_ids }}
      scope: ${{ needs.plan.outputs.scope }}
      full_units: ${{ needs.plan.outputs.full_units }}
      plan_digest: ${{ needs.plan.outputs.plan_digest }}
      base_sha: ${{ needs.plan.outputs.base_sha }}
      head_sha: ${{ needs.plan.outputs.head_sha }}
      cache_paths: "~/.bun/install/cache"
      cache_key_files: |
        package.json
        bun.lock
      unit_platform: linux-x64
      unit_trust: untrusted-ok
      unit_admission: github-hosted
  velnor-bun-velnor:
    name: "Bun · Bun package (velnor) · velnor — bun-velnor"
    if: ${{ always() && needs.plan.result == 'success' && contains(needs.plan.outputs.units, '"unit_id":"bun-velnor"') && (((github.event_name == 'workflow_dispatch' && contains(format(',{0},', github.event.inputs.providers), ',velnor,')) || (false)) && (!(github.event_name == 'pull_request' && (github.event.pull_request.head.repo.fork || github.event.pull_request.user.type == 'Bot')))) }}
    needs: [plan]
    uses: ./.github/workflows/ci-unit-bun.yml
    with:
      unit: bun-velnor
      provider: velnor
      selected_units: ${{ needs.plan.outputs.units }}
      selected_unit_ids: ${{ needs.plan.outputs.unit_ids }}
      scope: ${{ needs.plan.outputs.scope }}
      full_units: ${{ needs.plan.outputs.full_units }}
      plan_digest: ${{ needs.plan.outputs.plan_digest }}
      base_sha: ${{ needs.plan.outputs.base_sha }}
      head_sha: ${{ needs.plan.outputs.head_sha }}
      host_warm_layers: cargo
      unit_platform: linux-x64
      unit_trust: untrusted-ok
      unit_admission: velnor-trust-gated
  github-hosted-docker:
    name: "Docker · Docker · github-hosted — docker"
    if: ${{ always() && needs.plan.result == 'success' && contains(needs.plan.outputs.units, '"unit_id":"docker"') && (((github.event_name == 'workflow_dispatch' && contains(format(',{0},', github.event.inputs.providers), ',github-hosted,')) || (github.event_name != 'workflow_dispatch')) && (!(github.event_name == 'pull_request' && (github.event.pull_request.head.repo.fork || github.event.pull_request.user.type == 'Bot')))) }}
    needs: [plan]
    uses: ./.github/workflows/ci-unit-docker.yml
    with:
      unit: docker
      provider: github-hosted
      selected_units: ${{ needs.plan.outputs.units }}
      selected_unit_ids: ${{ needs.plan.outputs.unit_ids }}
      scope: ${{ needs.plan.outputs.scope }}
      full_units: ${{ needs.plan.outputs.full_units }}
      plan_digest: ${{ needs.plan.outputs.plan_digest }}
      base_sha: ${{ needs.plan.outputs.base_sha }}
      head_sha: ${{ needs.plan.outputs.head_sha }}
      cache_paths: ".velnor-docker-cache"
      seed_compat: "743cc362f16c"
      seed_dependency_files: |
        Cargo.lock
        Dockerfile
        docker/build-mise.lock
        docker/build-mise.toml
        rust-toolchain.toml
      seed_freshness_files: |
        Cargo.lock
        deny.toml
      unit_platform: linux-x64
      unit_trust: trusted-only
      unit_admission: github-hosted-trust-gated
  velnor-docker:
    name: "Docker · Docker · velnor — docker"
    if: ${{ always() && needs.plan.result == 'success' && contains(needs.plan.outputs.units, '"unit_id":"docker"') && (((github.event_name == 'workflow_dispatch' && contains(format(',{0},', github.event.inputs.providers), ',velnor,')) || (false)) && (!(github.event_name == 'pull_request' && (github.event.pull_request.head.repo.fork || github.event.pull_request.user.type == 'Bot')))) }}
    needs: [plan]
    uses: ./.github/workflows/ci-unit-docker.yml
    with:
      unit: docker
      provider: velnor
      selected_units: ${{ needs.plan.outputs.units }}
      selected_unit_ids: ${{ needs.plan.outputs.unit_ids }}
      scope: ${{ needs.plan.outputs.scope }}
      full_units: ${{ needs.plan.outputs.full_units }}
      plan_digest: ${{ needs.plan.outputs.plan_digest }}
      base_sha: ${{ needs.plan.outputs.base_sha }}
      head_sha: ${{ needs.plan.outputs.head_sha }}
      host_warm_layers: docker_seed
      unit_platform: linux-x64
      unit_trust: trusted-only
      unit_admission: velnor-trust-gated
  github-hosted-docs:
    name: "Documentation · Documentation · github-hosted — docs"
    if: ${{ always() && needs.plan.result == 'success' && contains(needs.plan.outputs.units, '"unit_id":"docs"') && ((github.event_name == 'workflow_dispatch' && contains(format(',{0},', github.event.inputs.providers), ',github-hosted,')) || (github.event_name != 'workflow_dispatch')) }}
    needs: [plan]
    uses: ./.github/workflows/ci-unit-docs.yml
    with:
      unit: docs
      provider: github-hosted
      selected_units: ${{ needs.plan.outputs.units }}
      selected_unit_ids: ${{ needs.plan.outputs.unit_ids }}
      scope: ${{ needs.plan.outputs.scope }}
      full_units: ${{ needs.plan.outputs.full_units }}
      plan_digest: ${{ needs.plan.outputs.plan_digest }}
      base_sha: ${{ needs.plan.outputs.base_sha }}
      head_sha: ${{ needs.plan.outputs.head_sha }}
      cache_paths: "~/.npm"
      cache_key_files: |
        package-lock.json
        bun.lock
      unit_platform: linux-x64
      unit_trust: untrusted-ok
      unit_admission: github-hosted
  velnor-docs:
    name: "Documentation · Documentation · velnor — docs"
    if: ${{ always() && needs.plan.result == 'success' && contains(needs.plan.outputs.units, '"unit_id":"docs"') && (((github.event_name == 'workflow_dispatch' && contains(format(',{0},', github.event.inputs.providers), ',velnor,')) || (false)) && (!(github.event_name == 'pull_request' && (github.event.pull_request.head.repo.fork || github.event.pull_request.user.type == 'Bot')))) }}
    needs: [plan]
    uses: ./.github/workflows/ci-unit-docs.yml
    with:
      unit: docs
      provider: velnor
      selected_units: ${{ needs.plan.outputs.units }}
      selected_unit_ids: ${{ needs.plan.outputs.unit_ids }}
      scope: ${{ needs.plan.outputs.scope }}
      full_units: ${{ needs.plan.outputs.full_units }}
      plan_digest: ${{ needs.plan.outputs.plan_digest }}
      base_sha: ${{ needs.plan.outputs.base_sha }}
      head_sha: ${{ needs.plan.outputs.head_sha }}
      host_warm_layers: cargo
      unit_platform: linux-x64
      unit_trust: untrusted-ok
      unit_admission: velnor-trust-gated
  github-hosted-opentofu:
    name: "OpenTofu · OpenTofu · github-hosted — opentofu"
    if: ${{ always() && needs.plan.result == 'success' && contains(needs.plan.outputs.units, '"unit_id":"opentofu"') && ((github.event_name == 'workflow_dispatch' && contains(format(',{0},', github.event.inputs.providers), ',github-hosted,')) || (github.event_name != 'workflow_dispatch')) }}
    needs: [plan]
    uses: ./.github/workflows/ci-unit-opentofu.yml
    with:
      unit: opentofu
      provider: github-hosted
      selected_units: ${{ needs.plan.outputs.units }}
      selected_unit_ids: ${{ needs.plan.outputs.unit_ids }}
      scope: ${{ needs.plan.outputs.scope }}
      full_units: ${{ needs.plan.outputs.full_units }}
      plan_digest: ${{ needs.plan.outputs.plan_digest }}
      base_sha: ${{ needs.plan.outputs.base_sha }}
      head_sha: ${{ needs.plan.outputs.head_sha }}
      cache_paths: "~/.terraform.d/plugin-cache"
      cache_key_files: "**/.terraform.lock.hcl"
      unit_platform: linux-x64
      unit_trust: untrusted-ok
      unit_admission: github-hosted
  velnor-opentofu:
    name: "OpenTofu · OpenTofu · velnor — opentofu"
    if: ${{ always() && needs.plan.result == 'success' && contains(needs.plan.outputs.units, '"unit_id":"opentofu"') && (((github.event_name == 'workflow_dispatch' && contains(format(',{0},', github.event.inputs.providers), ',velnor,')) || (false)) && (!(github.event_name == 'pull_request' && (github.event.pull_request.head.repo.fork || github.event.pull_request.user.type == 'Bot')))) }}
    needs: [plan]
    uses: ./.github/workflows/ci-unit-opentofu.yml
    with:
      unit: opentofu
      provider: velnor
      selected_units: ${{ needs.plan.outputs.units }}
      selected_unit_ids: ${{ needs.plan.outputs.unit_ids }}
      scope: ${{ needs.plan.outputs.scope }}
      full_units: ${{ needs.plan.outputs.full_units }}
      plan_digest: ${{ needs.plan.outputs.plan_digest }}
      base_sha: ${{ needs.plan.outputs.base_sha }}
      head_sha: ${{ needs.plan.outputs.head_sha }}
      host_warm_layers: cargo
      unit_platform: linux-x64
      unit_trust: untrusted-ok
      unit_admission: velnor-trust-gated
  prepare-cargo:
    name: "Control / Prepare Cargo"
    if: ${{ always() && needs.plan.result == 'success' && (contains(needs.plan.outputs.units, '"unit_id":"rust-unit-collector"') || contains(needs.plan.outputs.units, '"unit_id":"rust-velnor-bench"') || contains(needs.plan.outputs.units, '"unit_id":"rust-velnor-client"') || contains(needs.plan.outputs.units, '"unit_id":"rust-velnor-control"') || contains(needs.plan.outputs.units, '"unit_id":"rust-velnor-model"') || contains(needs.plan.outputs.units, '"unit_id":"rust-velnor-render"') || contains(needs.plan.outputs.units, '"unit_id":"rust-velnor-runner"') || contains(needs.plan.outputs.units, '"unit_id":"rust-velnor-tools"') || contains(needs.plan.outputs.units, '"unit_id":"rust-velnor-workflow"') || contains(needs.plan.outputs.units, '"unit_id":"rust-velnor-workflow-contract"') || contains(needs.plan.outputs.units, '"unit_id":"rust-velnorctl"') || contains(needs.plan.outputs.units, '"unit_id":"rust-production-topology"')) && ((((github.event_name == 'workflow_dispatch' && contains(format(',{0},', github.event.inputs.providers), ',velnor,')) || (false)) && (!(github.event_name == 'pull_request' && (github.event.pull_request.head.repo.fork || github.event.pull_request.user.type == 'Bot'))))) }}
    needs: [plan]
    uses: ./.github/workflows/ci-unit-rust.yml
    with:
      unit: rust-policy
      provider: control
      selected_units: ${{ needs.plan.outputs.units }}
      selected_unit_ids: ${{ needs.plan.outputs.unit_ids }}
      scope: ${{ needs.plan.outputs.scope }}
      full_units: ${{ needs.plan.outputs.full_units }}
      plan_digest: ${{ needs.plan.outputs.plan_digest }}
      base_sha: ${{ needs.plan.outputs.base_sha }}
      head_sha: ${{ needs.plan.outputs.head_sha }}
  github-hosted-rust-policy:
    name: "Rust · Rust dependency policy · github-hosted — rust-policy"
    if: ${{ always() && needs.plan.result == 'success' && contains(needs.plan.outputs.units, '"unit_id":"rust-policy"') && ((github.event_name == 'workflow_dispatch' && contains(format(',{0},', github.event.inputs.providers), ',github-hosted,')) || (github.event_name != 'workflow_dispatch')) }}
    needs: [plan]
    uses: ./.github/workflows/ci-unit-rust.yml
    with:
      unit: rust-policy
      provider: github-hosted
      selected_units: ${{ needs.plan.outputs.units }}
      selected_unit_ids: ${{ needs.plan.outputs.unit_ids }}
      scope: ${{ needs.plan.outputs.scope }}
      full_units: ${{ needs.plan.outputs.full_units }}
      plan_digest: ${{ needs.plan.outputs.plan_digest }}
      base_sha: ${{ needs.plan.outputs.base_sha }}
      head_sha: ${{ needs.plan.outputs.head_sha }}
      mbx_compat: ec62b8b58bab
      mbx_dependency_files: |
        .cargo/**
        Cargo.lock
        deny.toml
      mbx_freshness_files: |
        .cargo/audit.toml
        .cargo/deny.toml
        Cargo.lock
        audit.toml
        deny.toml
      cargo_bin_tools: cargo-deny
      cache_paths: |
        ~/.cargo/registry
        ~/.cargo/git
      cache_key_files: |
        .cargo/**
        Cargo.lock
        rust-toolchain.toml
        rust-toolchain
      unit_platform: linux-x64
      unit_trust: untrusted-ok
      unit_admission: github-hosted
  velnor-rust-policy:
    name: "Rust · Rust dependency policy · velnor — rust-policy"
    if: ${{ always() && needs.plan.result == 'success' && (needs.prepare-cargo.result == 'success' || needs.prepare-cargo.result == 'skipped') && contains(needs.plan.outputs.units, '"unit_id":"rust-policy"') && (((github.event_name == 'workflow_dispatch' && contains(format(',{0},', github.event.inputs.providers), ',velnor,')) || (false)) && (!(github.event_name == 'pull_request' && (github.event.pull_request.head.repo.fork || github.event.pull_request.user.type == 'Bot')))) }}
    needs: [plan, prepare-cargo]
    uses: ./.github/workflows/ci-unit-rust.yml
    with:
      unit: rust-policy
      provider: velnor
      selected_units: ${{ needs.plan.outputs.units }}
      selected_unit_ids: ${{ needs.plan.outputs.unit_ids }}
      scope: ${{ needs.plan.outputs.scope }}
      full_units: ${{ needs.plan.outputs.full_units }}
      plan_digest: ${{ needs.plan.outputs.plan_digest }}
      base_sha: ${{ needs.plan.outputs.base_sha }}
      head_sha: ${{ needs.plan.outputs.head_sha }}
      mise_tools: "aqua:EmbarkStudios/cargo-deny"
      host_warm_layers: "rustup,mold,mbx,cargo"
      unit_platform: linux-x64
      unit_trust: untrusted-ok
      unit_admission: velnor-trust-gated
  github-hosted-rust-unit-collector:
    name: "Rust · unit-collector · github-hosted — rust-unit-collector"
    if: ${{ always() && needs.plan.result == 'success' && contains(needs.plan.outputs.units, '"unit_id":"rust-unit-collector"') && ((github.event_name == 'workflow_dispatch' && contains(format(',{0},', github.event.inputs.providers), ',github-hosted,')) || (github.event_name != 'workflow_dispatch')) }}
    needs: [plan]
    uses: ./.github/workflows/ci-unit-rust.yml
    with:
      unit: rust-unit-collector
      provider: github-hosted
      selected_units: ${{ needs.plan.outputs.units }}
      selected_unit_ids: ${{ needs.plan.outputs.unit_ids }}
      scope: ${{ needs.plan.outputs.scope }}
      full_units: ${{ needs.plan.outputs.full_units }}
      plan_digest: ${{ needs.plan.outputs.plan_digest }}
      base_sha: ${{ needs.plan.outputs.base_sha }}
      head_sha: ${{ needs.plan.outputs.head_sha }}
      mise_tools: "aqua:nextest-rs/nextest/cargo-nextest"
      mbx_compat: f75156e9e834
      mbx_dependency_files: |
        .cargo/**
        Cargo.lock
        rust-toolchain
        rust-toolchain.toml
      mbx_freshness_files: |
        mise.lock
        tools/unit-collector/**/*.rs
        tools/unit-collector/benches/**
        tools/unit-collector/examples/**
        tools/unit-collector/src/**
        tools/unit-collector/tests/**
        tools/unit-collector/tests/fixtures/dependency-bump.jsonl
        tools/unit-collector/tests/fixtures/fresh.jsonl
        tools/unit-collector/tests/fixtures/touched-source.jsonl
      cache_paths: |
        ~/.cargo/registry
        ~/.cargo/git
      cache_key_files: |
        .cargo/**
        Cargo.lock
        rust-toolchain.toml
        rust-toolchain
      cargo_root: "tools/unit-collector"
      cargo_net_offline: true
      unit_platform: linux-x64
      unit_trust: untrusted-ok
      unit_admission: github-hosted
  velnor-rust-unit-collector:
    name: "Rust · unit-collector · velnor — rust-unit-collector"
    if: ${{ always() && needs.plan.result == 'success' && (needs.prepare-cargo.result == 'success' || needs.prepare-cargo.result == 'skipped') && contains(needs.plan.outputs.units, '"unit_id":"rust-unit-collector"') && (((github.event_name == 'workflow_dispatch' && contains(format(',{0},', github.event.inputs.providers), ',velnor,')) || (false)) && (!(github.event_name == 'pull_request' && (github.event.pull_request.head.repo.fork || github.event.pull_request.user.type == 'Bot')))) }}
    needs: [plan, prepare-cargo]
    uses: ./.github/workflows/ci-unit-rust.yml
    with:
      unit: rust-unit-collector
      provider: velnor
      selected_units: ${{ needs.plan.outputs.units }}
      selected_unit_ids: ${{ needs.plan.outputs.unit_ids }}
      scope: ${{ needs.plan.outputs.scope }}
      full_units: ${{ needs.plan.outputs.full_units }}
      plan_digest: ${{ needs.plan.outputs.plan_digest }}
      base_sha: ${{ needs.plan.outputs.base_sha }}
      head_sha: ${{ needs.plan.outputs.head_sha }}
      mise_tools: "aqua:nextest-rs/nextest/cargo-nextest"
      cargo_net_offline: true
      host_warm_layers: "rustup,mold,mbx,cargo"
      unit_platform: linux-x64
      unit_trust: untrusted-ok
      unit_admission: velnor-trust-gated
  github-hosted-rust-velnor-bench:
    name: "Rust · velnor-bench · github-hosted — rust-velnor-bench"
    if: ${{ always() && needs.plan.result == 'success' && contains(needs.plan.outputs.units, '"unit_id":"rust-velnor-bench"') && ((github.event_name == 'workflow_dispatch' && contains(format(',{0},', github.event.inputs.providers), ',github-hosted,')) || (github.event_name != 'workflow_dispatch')) }}
    needs: [plan]
    uses: ./.github/workflows/ci-unit-rust.yml
    with:
      unit: rust-velnor-bench
      provider: github-hosted
      selected_units: ${{ needs.plan.outputs.units }}
      selected_unit_ids: ${{ needs.plan.outputs.unit_ids }}
      scope: ${{ needs.plan.outputs.scope }}
      full_units: ${{ needs.plan.outputs.full_units }}
      plan_digest: ${{ needs.plan.outputs.plan_digest }}
      base_sha: ${{ needs.plan.outputs.base_sha }}
      head_sha: ${{ needs.plan.outputs.head_sha }}
      mise_tools: "aqua:nextest-rs/nextest/cargo-nextest"
      mbx_compat: "9874c4732ec4"
      mbx_dependency_files: |
        .cargo/**
        Cargo.lock
        rust-toolchain
        rust-toolchain.toml
      mbx_freshness_files: |
        config/fleet/**
        crates/velnor-bench/**/*.rs
        crates/velnor-bench/benches/**
        crates/velnor-bench/examples/**
        crates/velnor-bench/src/**
        crates/velnor-bench/tests/**
        crates/velnor-control/**/*.rs
        crates/velnor-control/benches/**
